    """

    # If batch is a torch.Tensor, move it to the CUDA device
    if isinstance(batch, torch.Tensor):
        return batch.to(device)

    # If batch is a list or tuple, recursively call to_cuda on each element
    elif isinstance(batch, (list, tuple)):
        return type(batch)(to_cuda(item, device, ignore_list) for item in batch)

    # If batch is a dictionary, recursively call to_cuda on each value
    elif isinstance(batch, dict):
        # Ignore values with key "meta"
