import numpy as np
from typing import Union

def add_batch(batch: Union[tuple, list, dict, torch.Tensor, np.ndarray]) -> Union[torch.Tensor, np.ndarray]:
    """
    This function recursively adds a new dimension to the input data structure (which can be a batch of data in various formats such as tuple, list, dictionary, torch.Tensor, or numpy.ndarray) at the zeroth position. It is designed to handle nested data structures by applying the same operation to each element.

    Input-Output Arguments
    :param batch: Union[tuple, list, dict, torch.Tensor, np.ndarray]. The input data which can be a single item or a batch of items in various formats. The function processes this data by adding a new dimension to it or its elements.
    :return: Union[torch.Tensor, np.ndarray]. The modified batch with an added dimension at the zeroth position. This return type ensures compatibility with PyTorch and NumPy data structures.
    """

    # Check if the input is a tensor or array, and add a new dimension if it's not already a batch
    if isinstance(batch, (torch.Tensor, np.ndarray)):
        # Check if the tensor or array has more than one dimension
        if len(batch.shape) > 1:
            # If it has more than one dimension, return the tensor or array as is
            return batch
        else:
            # If it has only one dimension, add a new dimension at the zeroth position
            return batch.unsqueeze(0)

    # If the input is not a tensor or array, try to recursively add a new dimension to each element
    elif isinstance(batch, (tuple, list)):
        # Use a list comprehension to recursively add a new dimension to each element in the tuple or list
        return torch.stack([add_batch(item) for item in batch])

    # If the input is a dictionary, recursively add a new dimension to each value
    elif isinstance(batch, dict):
        # Use a dictionary comprehension to recursively add a new dimension to each value in the dictionary
        return torch.stack([add_batch(value) for value in batch.values()])

    # If the input is not a supported type, raise a TypeError
    else:
        raise TypeError("Unsupported input type. Only tuples, lists, dictionaries, tensors, and arrays are supported.")
